INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('b6617db7-3178-4a31-bbc6-420bd1e8c605','db618e68-0656-4b9b-b308-81e071faf745','Xolani','complete','{"age":"TBD","era":"500–1300 AD-inspired fantasy","name":"Xolani","race":"Human","alias":"","gender":"Male","titles":"The Vessel of Mvula\nThe Reluctant Vessel\nChronicler of Souls","subrace":"","summary":"Xolani is a spirit-bound mystic from Kwaye-Zulu in the Stone Mountains. After using a forbidden Binding Cadence to enslave the restless spirit Mvula during the Great Drought, he was cursed with the Dead Eye and forced to perceive the living and spirit worlds simultaneously. Now an exile, he uses his sacred Asalato and Crossroads magic to protect others while carrying the spiritual debt created by his mistake.","heritage":"Kwaye-Zulu","homeland":"Stone Mountains","pronouns":"He/Him","birthDate":"TBD","nicknames":"","occupation":"Spirit-bound mystic","affiliation":"Kwaye-Zulu","apparentAge":"Adult","canonStatus":"Canon","nameMeaning":"Peace","nationality":"","spoilerLevel":"TBD","pronunciation":"sho-LAH-nee","currentResidence":"Wandering exile","elementalHeritage":""}','{"build":["Wiry","Sinewy","Lean"],"nails":["Natural dark nails"],"eyeHex":["#4A2D1C","#E5E1D8"],"height":"6''2\" (188 cm)","makeup":"","weight":"TBD","hairHex":["#0B0908"],"skinHex":["#593A2D","#3E2A23"],"eyeColor":["Right eye — deep brown","Left eye — milky white"],"grooming":"Weathered but deliberate","skinTone":["Mahogany-charcoal brown"],"wardrobe":"Tattered cloak\nLayered wraps\nLoose trousers\nLeather footwear\nWeathered work clothing","hairColor":["Black"],"hairStyle":"Long voluminous locs with beads","accessories":"Beaded necklaces\nRitual charms\nBone tokens\nMetal rings\nTobacco pouch\nSmall rum flask","faceDetails":["High sharp cheekbones","Straight nose","Strong elegant jawline"],"hairTexture":["Locs"],"colorPalette":"Charcoal black\nEarth brown\nAsh grey\nAntique bronze\nBone white","dominantHand":"TBD","outfitColors":"#0D0C0B\n#211B18\n#4A382B\n#8A6743\n#B9B0A2","alternateForm":"","clothingStyle":"Practical Stone Mountains attire with dark layered fabrics, weathered materials, beadwork, ritual accessories, and an understated mystical silhouette suited to a wandering spirit practitioner.","appearanceNotes":"Xolani should appear striking and regal despite his exhausted, haunted presence. His right eye remains naturally brown while the left Dead Eye is completely milky-white and pupil-less. Fine charcoal-grey veins radiate from the left socket and become more pronounced when Mvula is active.","outfitMaterials":["Worn cloth","Leather","Canvas","Wood","Bone","Metal"],"postureMovement":["Predatory grace","Controlled movements","Rhythmic hand movement"],"signatureOutfit":"Layered dark ritual clothing with a weathered cloak, practical wraps, loose trousers, leather footwear, beadwork, necklaces, and subtle spiritual symbols. His clothing is worn and functional rather than ceremonial.","distinguishingFeatures":["Milky-white Dead Eye","Charcoal-grey eye veins","Scarred hands","Calloused palms","Ash-stained fingertips","Cold left hand","Long beaded locs"]}','{"fears":["Losing control to Mvula","Repeating his original mistake","Being pulled into the spirit realm","Mvula being forgotten","Breaking his rhythm in combat"],"goals":["Find spiritual peace","Atone for binding Mvula","Protect others from restless spirits","Keep Mvula from being forgotten"],"beliefs":["Every soul deserves remembrance","Spirits are not servants","Power creates responsibility","The dead deserve dignity","Peace requires accountability"],"culture":["Kwaye-Zulu","High Crossroads keepers","Rhythm-based spiritual tradition"],"lineage":"Kwaye-Zulu spiritual tradition","storyArc":"Xolani begins as a guilt-ridden exile enduring Mvula''s hatred as punishment for his past. Through remembrance, shared rituals, and stubborn compassion, their parasitic bond gradually develops into reluctant mutual recognition. His journey centers on accountability, remembrance, and discovering whether peace can exist without erasing what happened.","backstory":"During the Great Drought, Xolani became desperate to save his starving village. Against his master''s warnings, he climbed to the Altar of the Unburied and used a forbidden Binding Cadence to imprison the restless spirit Mvula within his Asalato. The ritual produced Black Rain and saved the village, but Mvula retaliated by spiritually overwriting Xolani''s left eye, creating the Dead Eye. Marked by the curse and ashamed of what he had done, Xolani left Kwaye-Zulu and became a wandering protector who works to repay his debt to the spirit world.","childhood":"Xolani grew up in Kwaye-Zulu, where rhythm was woven into birth, mourning, spiritual practice, and everyday life. He showed unusual sensitivity to spirits and became a talented apprentice in the village''s spiritual traditions.","lifestyle":["Wanders between settlements","Handles dangerous spirit problems","Practices rhythmic meditation","Carries ritual offerings","Keeps his Asalato nearby"],"storyRole":"Xolani serves as a bridge between the living and the forgotten dead. His abilities make him exceptionally dangerous against spiritual threats, while his relationship with Mvula forces him to confront the consequences of treating a suffering soul as a source of power.","birthplace":"Kwaye-Zulu, Stone Mountains","psychology":["Burdened by guilt","Spiritually exhausted","Highly self-controlled","Protective of forgotten souls","Resists Mvula''s influence"],"motivations":["Repay his spiritual debt","Protect the living","Remember forgotten souls","Preserve Mvula''s memory","Prevent similar mistakes"],"personality":["Stoic","Weary","Reserved","Compassionate","Remorseful","Protective","Disciplined","Observant","Stubborn"],"voiceSpeech":["Deep soulful baritone","Quiet delivery","Measured speech","Few words","Emotionally restrained"],"likesDislikes":["Likes rainfall","Likes natural beauty","Values quiet","Values remembrance","Dislikes spiritual exploitation","Dislikes arrogant magic"],"majorLifeEvents":"Born in Kwaye-Zulu\nTrained in spiritual rhythms\nGreat Drought strikes Kwaye-Zulu\nClimbs the Altar of the Unburied\nBinds Mvula against his will\nSummons the Black Rain\nReceives the Dead Eye curse\nLeaves Kwaye-Zulu in exile\nBecomes a wandering spirit protector\nDevelops The Stillness"}','{"weapons":"Sacred Asalato","strengths":"Exceptional rhythm\nSpirit perception\nMental discipline\nPrecise coordination\nBattlefield control\nSpiritual resistance\nClose-range weapon skill","weaknesses":"Silence magic\nBroken rhythm\nSpiritual debt\nConsecrated ground\nSacred salt\nFlorida Water","combatStyle":["Rhythmic combat","Asalato striking","Spiritual disruption","Kinetic control","Short-range teleportation","Psychological warfare"],"limitations":["Magic depends on vibration","Missed rhythms cause backlash","Spirit invocation drains vitality","Mvula can sabotage movement","Cannot harm the truly innocent","13th Gate damages his senses"],"powerSource":["Crossroads spirit magic","Asalato rhythm","Mvula''s spiritual influence","Dead Eye"],"abilityNotes":"The swish of the Asalato sustains flow-based effects while the clack acts as a spiritual trigger. Xolani''s strongest techniques depend on uninterrupted timing. His Dead Eye allows direct perception of spirits and can expose others to the Grey Space through Eye-Lock.","combatProfile":"Xolani fights through rhythm rather than brute force. Continuous Asalato patterns control movement, summon spiritual interference, distort kinetic energy, and create openings for precise physical strikes. Mvula can either disrupt Xolani''s coordination or protect him from lethal attacks, making every battle a simultaneous struggle against the enemy and the spirit within him.","weaponDetails":"Xolani fights with paired Asalato, also known as Kashaka or shaker balls. Their swish sustains rhythmic magic while their clack releases or locks spiritual force. His combat set is reinforced for physical strikes and spiritually linked to Mvula.","transformations":"The 13th Gate state","primaryAbilities":"Rattling Call\nSoul-Clack\nPapa Legba''s Gate\nEye-Lock","secondaryAbilities":"Syncopated Stasis\nSpirit perception\nKinetic distortion\nSpectral summoning\nSpiritual binding","signatureTechniques":"Crossroads Cadence\nPolyrhythmic Paradox\nLateral Click — X-Snap\nThe Stillness\nThe 13th Gate","transformationDetails":"During The 13th Gate, Xolani breaks open his Asalato and spills their spirit dirt around himself, temporarily becoming a manifestation of the Crossroads. For roughly sixty seconds, his spiritual perception and temporal attacks become extreme. The technique leaves him temporarily blind and deaf afterward."}','{"allies":"Mvula — Bound spirit and reluctant guardian\nSekani — Ally and musical counterpart","rivals":"","enemies":"","mentors":"Kwaye-Zulu village elder — Former spiritual mentor","parents":"","partner":"TBD","children":"","siblings":"","worldConnections":"Stone Mountains\nKwaye-Zulu\nAltar of the Unburied\nHigh Crossroads\nGrey Space","relationshipNotes":"Xolani and Mvula began as jailer and captive after Xolani forcibly bound the spirit during the Great Drought. Mvula initially tormented and sabotaged him, but Xolani''s refusal to forget Mvula''s human life gradually changes their relationship. They remain spiritually fused, contentious, and emotionally complicated, with Mvula increasingly protecting the only living person who continues to remember him."}','{"tbdFields":"Birth date\nExact age\nWeight\nDominant hand\nParents\nSiblings\nPartner\nExact current residence\nFormer mentor name","canonLocks":"Human male\n6''2\" height\nMahogany-charcoal brown skin\nLong black beaded locs\nBrown right eye\nMilky-white left Dead Eye\nCharcoal-grey veins around Dead Eye\nBorn in Kwaye-Zulu\nOriginates from Stone Mountains\nMvula bound to Dead Eye\nUses Asalato in combat\nCreated Dead Eye through forbidden binding\nBlack Rain occurred during Great Drought\nXolani lives as an exile\nMvula was forcibly bound","galleryUrl":"","mediaNotes":"Use the established Xolani production artwork as the primary visual continuity reference. Future portraits, combat artwork, album covers, and production assets should preserve his face, complexion, Dead Eye placement, locs, clothing silhouette, jewelry, and Asalato design.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b6617db7-3178-4a31-bbc6-420bd1e8c605/portrait/1790320005150-xolani-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nFull-Body Front — Done\nBack View — Done\nFace Reference — Done\nEye Reference — Done\nHair Reference — Done\nOutfit Breakdown — Done\nWeapon Reference — Done\nCombat Reference — Done","productionNotes":"Maintain Xolani''s established dark anime-fantasy design across all future artwork. His mahogany-charcoal complexion, long beaded locs, lean 6''2\" silhouette, Dead Eye, charcoal veins, layered dark clothing, ritual jewelry, and Asalato are defining visual anchors. Mvula''s manifestations should appear as charcoal shadow, smoke, and ash rather than replacing Xolani''s own silhouette.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b6617db7-3178-4a31-bbc6-420bd1e8c605/reference/1790320018088-xolani-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b6617db7-3178-4a31-bbc6-420bd1e8c605/alternate/1790320022686-xolani-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b6617db7-3178-4a31-bbc6-420bd1e8c605/portrait/1790320005150-xolani-character-portrait.png',6,1,1,'c6c8934d-b274-44f7-a1a6-a6f8f959654b','c68d60d1-883a-4683-8000-a9cd9d0d4d2a','cb4c27cc-2adb-4d75-92b0-a1cabfa13127','2ff89f94-94cb-4de0-a6a8-8b4e3925f455','2026-09-25T07:08:45.164033+00:00');

INSERT OR REPLACE INTO studio_characters (id,user_id,name,status,identity,appearance,origin_lore,abilities,relationships,media,portrait_url,current_step,is_complete,is_public,realm_record_id,race_record_id,faction_record_id,family_record_id,updated_at) VALUES ('b4f84058-548a-4ea6-ac43-f83d7cc7275e','db618e68-0656-4b9b-b308-81e071faf745','Kusa-No-Shin Durasurya','complete','{"age":"28","era":"500–1300 AD-inspired fantasy","name":"Kusa-No-Shin Durasurya","race":"Human","alias":"The Flickering Phantom","gender":"Male","titles":"The Flickering Phantom\nThe Emerald Vagabond\nThe Laughing Healer\nThe Keeper of Nine Clouds\nKaelen’s Greatest Headache","subrace":"Durskari-Sunspear","summary":"Kusa-No-Shin Durasurya is a mixed Durskari and Sunspear healer, smoke mage, and swordsman known as the Flickering Phantom. His Adaptive Flux shifts between energetic Sativa Flow, heavy Indica Stasis, and a balanced Hybrid state. Relaxed, compassionate, spiritual, and deceptively formidable, Kusa restores physical and emotional balance while serving as one of Kaelen’s most trusted companions.","heritage":"Durskari and Sunspear","homeland":"Umbral Empire","pronouns":"He/Him","birthDate":"TBD","nicknames":"Kusa","occupation":"Healer, smoke mage, swordsman","affiliation":"Kaelen’s crew","apparentAge":"Late 20s","canonStatus":"Canon","nameMeaning":"TBD","nationality":"TBD","spoilerLevel":"TBD","pronunciation":"TBD","currentResidence":"TBD","elementalHeritage":"Adaptive Flux"}','{"build":["Lean","Athletic"],"nails":["Natural"],"eyeHex":["#86E8B5","#9B72CF"],"height":"6''2\"","makeup":"","weight":"TBD","hairHex":["#171312"],"skinHex":["#6B3F2A","#A66A3F"],"eyeColor":["Mint green","Soft amethyst"],"grooming":"Neatly maintained braids and locks.","skinTone":["Deep bronze-ebony","Golden undertones"],"wardrobe":"Asymmetrical hitare-inspired robe\nLayered trousers\nBraided rope belt\nPeriod sandals","hairColor":["Black"],"hairStyle":"Braided sides with shoulder-length textured locks.","accessories":"Wooden hair beads\nCopper hair rings\nEmerald charms\nCowrie shells\nBeaded necklaces\nGrandmother Zu gourd","faceDetails":["Defined jawline","Relaxed expression","Half-lidded gaze","Lopsided grin"],"hairTexture":["Thick 4C coils","Springy textured locks"],"colorPalette":"Emerald green #2F6B4F\nMint #86E8B5\nDeep plum #4A235A\nAmethyst #9B72CF\nAntique gold #B58A45\nEbony #171312","dominantHand":"TBD","outfitColors":"Emerald green\nDeep plum\nBlack\nAntique gold\nNatural brown","alternateForm":["Sativa Flow State","Indica Stasis State","Balanced Hybrid State","Nine-Cloud Nirvana"],"clothingStyle":"Loose early-period fantasy garments blending Durskari and Sunspear influences. His clothing favors unrestricted movement, natural materials, asymmetry, and an emerald-and-plum visual split representing Adaptive Flux.","appearanceNotes":"His visual identity centers on duality. Emerald represents Sativa Flow and amethyst represents Indica Stasis. In Balanced State, one eye remains mint green and the other amethyst. His design should remain relaxed and approachable even when displaying dangerous magical power.","outfitMaterials":["Woven cloth","Braided rope","Leather","Wood","Copper","Brass"],"postureMovement":["Relaxed posture","Fluid movement","Unpredictable footwork"],"signatureOutfit":"An asymmetrical early-period hitare-inspired robe divided between emerald green and deep plum. A thick braided rope belt secures the layered garments, while Grandmother Zu hangs at his side. Sandals, beads, copper rings, emerald charms, and period-inspired accessories complete the wandering swordsman silhouette.","distinguishingFeatures":["Mint-green left eye","Amethyst right eye","Beaded textured locks","Green smoke wisps","Relaxed grin"]}','{"fears":["TBD"],"goals":["Protect Kaelen’s crew","Maintain spiritual balance","Master Adaptive Flux"],"beliefs":["Strength requires peace","Peace requires strength","Balance requires both","Burden should be shared"],"culture":["Durskari","Sunspear"],"lineage":"Mixed Durskari and Sunspear ancestry.","storyArc":"TBD","backstory":"Kusa became known as the Flickering Phantom through his unusual mastery of Adaptive Flux, healing arts, smoke manipulation, and swordsmanship. His connection to the ancestral Zucca Gourd known as Grandmother Zu and his friendship with Kaelen are established parts of his identity. Further details of his early life remain TBD.","childhood":"TBD","lifestyle":["Talks to butterflies","Names rocks","Collects stray spirits","Meditates","Carries herbal supplies"],"storyRole":"Kusa serves as the healer and Adaptive Flux specialist of Kaelen’s crew. His seemingly unserious personality contrasts with his importance to the group, especially when Kaelen’s Demon Blot becomes unstable. He provides physical recovery, emotional grounding, battlefield control, and unpredictable tactical support.","birthplace":"TBD","psychology":["Values emotional balance","Highly empathetic","Observant beneath humor","Comfortable with silence"],"motivations":["Protect his companions","Restore balance","Ease suffering","Keep Kaelen grounded"],"personality":["Compassionate","Emotionally intelligent","Spiritual","Distractible","Goofy","Relaxed","Wise","Unpredictable","Supportive"],"voiceSpeech":["Relaxed speech","Playful observations","Spiritual metaphors","Casual humor","Calls others friend"],"likesDislikes":["Likes peaceful environments","Likes butterflies","Likes nature","Likes good vibes","Dislikes unnecessary tension"],"majorLifeEvents":"Inherited Grandmother Zu\nMastered Adaptive Flux\nJoined Kaelen’s crew\nBecame Kaelen’s trusted healer"}','{"weapons":"Verdant Eclipse — Chronic Katana\nGrandmother Zu — Zucca Gourd","strengths":"Battlefield control\nHealing support\nAdaptive combat\nSwordsmanship\nUnpredictable movement\nEmotional awareness\nPain management","weaknesses":"Easily distracted\nUnconventional focus","combatStyle":["Emerald Mirage Style","Durskari rhythm footwork","Sunspear sword forms","Adaptive smoke manipulation"],"limitations":["TBD"],"powerSource":["Adaptive Flux","Smoke magic","Spiritual energy"],"abilityNotes":"Emerald Reprieve suppresses pain and exhaustion temporarily rather than simply closing wounds. Soul Mulch converts negative emotional energy into restorative life force. Gentle Monsoon calms panic and helps restore clarity. His Adaptive Flux is also capable of helping suppress the effects of Kaelen’s Demon Blot.\n\nPreserve the contrast between Kusa’s goofy behavior and genuine spiritual wisdom. His relaxed personality should never erase his competence as a healer and swordsman.","combatProfile":"Kusa fights through constant shifts in tempo. Sativa Flow emphasizes speed and mental overstimulation, while Indica Stasis emphasizes heaviness and battlefield suppression. Hybrid Flux combines both states with deceptive movement, smoke clones, and sensory disruption. His healing techniques allow him to stabilize allies while remaining an active combatant.","weaponDetails":"Verdant Eclipse is an early curved tachi forged from Emerald Steel. Its hollow Dragon-Resin hilt functions as a pipe, while microscopic channels carry magical smoke through the blade. The sword becomes thin and green during Sativa Flow, heavier and violet during Indica Stasis, and semi-transparent with coiling smoke during Hybrid Flux. Grandmother Zu is an ancestral ceremonial gourd decorated with cowrie shells, sandalwood beads, emerald gemstones, and brass Sunspear etchings.","transformations":"Sativa Flow State\nIndica Stasis State\nBalanced Hybrid State\nNine-Cloud Nirvana — Garden of the Emerald Scale","primaryAbilities":"Sativa Flow\nIndica Stasis\nHybrid Flux\nSmoke manipulation\nRestorative balance\nTemporal anaesthesia","secondaryAbilities":"Pain suppression\nEmotional stabilization\nSmoke clones\nSensory disruption\nGravity-like suppression\nCerebral overstimulation","signatureTechniques":"Flux-Flicker Dash\nCouch-Lock Cloud\nGiggling Mist\nEmerald Reprieve\nSoul Mulch\nGentle Monsoon\nBreath of Flux\nNine-Cloud Nirvana","transformationDetails":"Sativa Flow turns both eyes luminous mint with vine-like pupils and emphasizes speed and cerebral energy. Indica Stasis turns both eyes deep violet while emphasizing heaviness and suppression. Balanced Hybrid State preserves one green and one purple eye. Nine-Cloud Nirvana transforms the battlefield into nine floating cloud platforms inhabited by Strain Spirits and manifests the Zenith Dragon."}','{"allies":"Kaelen — Trusted companion and crew leader","rivals":"","enemies":"","mentors":"","parents":"TBD","partner":"TBD","children":"","siblings":"TBD","worldConnections":"Umbral Empire\nDurskari heritage\nSunspear heritage\nKaelen’s crew","relationshipNotes":"Kusa is one of the people Kaelen trusts completely. Although his relaxed behavior frequently clashes with Kaelen’s structured tactical planning, Kusa understands him deeply. His Adaptive Flux helps prevent the Demon Blot affecting Kaelen’s arm from overwhelming him, and Kusa supports him without fear or judgment."}','{"tbdFields":"Pronunciation\nName meaning\nBirth date\nSpoiler level\nNationality\nCurrent residence\nBirthplace\nParents\nSiblings\nPartner\nWeight\nDominant hand\nChildhood\nDetailed story arc\nSpecific fears\nAbility limitations","canonLocks":"Name: Kusa-No-Shin Durasurya\nAge: 28\nMale\nHe/Him\nDurskari and Sunspear heritage\nHeight: 6''2\"\nDeep bronze-ebony skin\nBlack textured locks\nMint and amethyst eyes\nAdaptive Flux\nEmerald Mirage Style\nVerdant Eclipse\nGrandmother Zu\nKaelen’s crew\nHealer role\nNine-Cloud Nirvana\nEmerald and plum color identity","galleryUrl":"","mediaNotes":"Character portrait and refined visual reference have been created. All future artwork should preserve established facial features, complexion, hair texture and style, lean build, emerald-and-plum clothing palette, dual-state eyes, Grandmother Zu, and Verdant Eclipse.","galleryUrls":[],"portraitUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b4f84058-548a-4ea6-ac43-f83d7cc7275e/portrait/1790319871004-kusa-no-shin-character-portrait.png","visualAssets":"Character Portrait — Done\nReference / Production Sheet — Done\nFull-Body Front — Needed\nBack View — Needed\nLeft View — Needed\nRight View — Needed\nFace Reference — Done\nEye Reference — Done\nHair Reference — Needed\nOutfit Breakdown — Needed\nWeapon Reference — Done\nExpression Sheet — Needed\nCombat Reference — Needed\nNine-Cloud Nirvana Reference — Needed\nGrandmother Zu Reference — Done","productionNotes":"Use the refined Kusa-No-Shin artwork as the primary visual direction. Maintain his deep bronze-ebony complexion, textured black locks with braided sides, lean athletic build, emerald-and-plum asymmetrical clothing, dual-colored eyes, Grandmother Zu, and Verdant Eclipse. Future production sheets should preserve the same facial structure and period-inspired fantasy design.","referenceArtUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b4f84058-548a-4ea6-ac43-f83d7cc7275e/reference/1790319878935-kus-no-shin-reference-production-sheet.png","alternateFormUrl":"https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b4f84058-548a-4ea6-ac43-f83d7cc7275e/alternate/1790319885670-kusa-no-shin-alternate-true-form.png"}','https://dblwgpiiwkjhdegsindx.supabase.co/storage/v1/object/public/studio-character-media/db618e68-0656-4b9b-b308-81e071faf745/b4f84058-548a-4ea6-ac43-f83d7cc7275e/portrait/1790319871004-kusa-no-shin-character-portrait.png',6,1,1,'81dcaa1f-296e-4e34-98c5-c69907431fc7','c68d60d1-883a-4683-8000-a9cd9d0d4d2a','f5492e8b-d617-44b1-bce7-517c90d1da55','c5625a0b-727b-4792-8128-f8aceb92186a','2026-09-25T07:08:43.146966+00:00');

